"use strict";const CLAVE_ALMACENAMIENTO="agenda-academica-tareas",formulario=document.querySelector("#formulario-tarea"),entrada=document.querySelector("#nombre-tarea"),lista=document.querySelector("#lista-tareas"),listaVacia=document.querySelector("#lista-vacia"),contador=document.querySelector("#contador"),mensaje=document.querySelector("#mensaje");let tareas=cargarTareas();function cargarTareas(){try{const e=localStorage.getItem(CLAVE_ALMACENAMIENTO);if(null===e)return[];const a=JSON.parse(e);if(!Array.isArray(a))throw new Error("Formato de almacenamiento incorrecto.");return a.filter(e=>null!==e&&"object"==typeof e&&"string"==typeof e.id&&"string"==typeof e.nombre&&"boolean"==typeof e.completada)}catch(e){return mensaje.textContent="No fue posible recuperar las tareas guardadas. Comprueba que el navegador permita el almacenamiento local.",[]}}function guardarTareas(){try{localStorage.setItem(CLAVE_ALMACENAMIENTO,JSON.stringify(tareas)),mensaje.textContent=""}catch(e){mensaje.textContent="Los cambios están visibles, pero no pudieron guardarse. Se perderán al recargar la página."}}function mostrarTareas(){lista.replaceChildren();const e=tareas.filter(e=>e.completada).length;contador.textContent=`${e} de ${tareas.length} completadas`,listaVacia.hidden=tareas.length>0,tareas.forEach(e=>{const a=document.createElement("li");a.className="tarea",e.completada&&a.classList.add("completada");const t=document.createElement("label"),r=document.createElement("input");r.type="checkbox",r.checked=e.completada,r.addEventListener("change",()=>{e.completada=r.checked,guardarTareas(),mostrarTareas()});const n=document.createElement("span");n.textContent=e.nombre;const o=document.createElement("button");o.type="button",o.className="boton-eliminar",o.textContent="Eliminar",o.setAttribute("aria-label",`Eliminar tarea: ${e.nombre}`),o.addEventListener("click",()=>{tareas=tareas.filter(a=>a.id!==e.id),guardarTareas(),mostrarTareas()}),t.append(r,n),a.append(t,o),lista.append(a)})}formu